package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonObjectFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.UnwrappingBeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.std.StringSerializer;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanPropertyWriter_serializeAsField_TriageGen2Test {

    private BeanPropertyWriter writer;
    private JsonGenerator jgen;
    private SerializerProvider prov;
    private PropertySerializerMap map;
    private JsonSerializer<Object> serializer;
    private JsonSerializer<Object> nullSerializer;
    private JavaType javaType;

    // Marker for empty suppression test
    private static final Object MARKER_FOR_EMPTY = new Object();

    @Before
    public void setUp() throws Exception {
        jgen = mock(JsonGenerator.class);
        prov = mock(SerializerProvider.class);
        map = mock(PropertySerializerMap.class);
        serializer = mock(JsonSerializer.class);
        nullSerializer = mock(JsonSerializer.class);
        javaType = mock(JavaType.class);

        // Using a concrete subclass or reflection since BeanPropertyWriter is often instantiated via factories
        // For testing purposes, we mock the behavior of the internal fields via reflection if necessary, 
        // but here we will try to use the protected constructor if accessible or mock the class.
        // Since we cannot easily instantiate BeanPropertyWriter without a Member, we mock it.
        writer = mock(BeanPropertyWriter.class, CALLS_REAL_METHODS);

        // Injecting private fields using reflection to simulate the internal state of BeanPropertyWriter
        setInternalState(writer, "_name", Mockito.mock(com.fasterxml.jackson.core.io.SerializedString.class));
        setInternalState(writer, "_dynamicSerializers", map);
        setInternalState(writer, "_serializer", null); // Start with null to test dynamic lookup
        setInternalState(writer, "_nullSerializer", null);
        setInternalState(writer, "_typeSerializer", null);
        setInternalState(writer, "_suppressableValue", null);
    }

    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testSerializeAsField_NullValue_WithNullSerializer() throws Exception {
        Object bean = new Object();
        setInternalState(writer, "_name", mock(com.fasterxml.jackson.core.io.SerializedString.class));
        setInternalState(writer, "_nullSerializer", nullSerializer);
        when(writer.get(bean)).thenReturn(null);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(nullSerializer).serialize(eq(null), eq(jgen), eq(prov));
    }

    @Test
    public void testSerializeAsField_NullValue_NoNullSerializer() throws Exception {
        Object bean = new Object();
        setInternalState(writer, "_nullSerializer", null);
        when(writer.get(bean)).thenReturn(null);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_NormalValue_WithExistingSerializer() throws Exception {
        Object bean = new Object();
        Object value = "test";
        setInternalState(writer, "_serializer", serializer);
        when(writer.get(bean)).thenReturn(value);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_DynamicSerializerLookup_Success() throws Exception {
        Object bean = new Object();
        Object value = "test";
        setInternalState(writer, "_serializer", null);
        when(writer.get(bean)).thenReturn(value);
        when(map.serializerFor(value.getClass())).thenReturn(serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_DynamicSerializerLookup_FindAndAdd() throws Exception {
        Object bean = new Object();
        Object value = "test";
        setInternalState(writer, "_serializer", null);
        when(writer.get(bean)).thenReturn(value);
        when(map.serializerFor(value.getClass())).thenReturn(null);
        // Mocking protected _findAndAddDynamic
        doReturn(serializer).when(writer)._findAndAddDynamic(eq(map), eq(value.getClass()), eq(prov));

        writer.serializeAsField(bean, jgen, prov);

        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_SuppressEmptyValue() throws Exception {
        Object bean = new Object();
        Object value = ""; // Assume this is "empty"
        setInternalState(writer, "_serializer", serializer);
        setInternalState(writer, "_suppressableValue", MARKER_FOR_EMPTY);
        when(writer.get(bean)).thenReturn(value);
        when(serializer.isEmpty(value)).thenReturn(true);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_SuppressSpecificValue() throws Exception {
        Object bean = new Object();
        Object value = "suppress_me";
        setInternalState(writer, "_serializer", serializer);
        setInternalState(writer, "_suppressableValue", "suppress_me");
        when(writer.get(bean)).thenReturn(value);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerializeAsField_NotSuppressedValue() throws Exception {
        Object bean = new Object();
        Object value = "keep_me";
        setInternalState(writer, "_serializer", serializer);
        setInternalState(writer, "_suppressableValue", "suppress_me");
        when(writer.get(bean)).thenReturn(value);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsField_SelfReference() throws Exception {
        Object bean = new Object();
        setInternalState(writer, "_serializer", serializer);
        when(writer.get(bean)).thenReturn(bean); // value == bean

        writer.serializeAsField(bean, jgen, prov);

        verify(writer)._handleSelfReference(eq(bean), eq(serializer));
        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(bean, jgen, prov);
    }

    @Test
    public void testSerializeAsField_WithTypeSerializer() throws Exception {
        Object bean = new Object();
        Object value = "test";
        JsonSerializer<Object> typeSer = mock(JsonSerializer.class);
        setInternalState(writer, "_serializer", serializer);
        setInternalState(writer, "_typeSerializer", typeSer);
        when(writer.get(bean)).thenReturn(value);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serializeWithType(value, jgen, prov, typeSer);
        verify(serializer, never()).serialize(any(), any(), any());
    }
}
